import { useMemo, useState } from 'react';

export type UserStatus = 'active' | 'disabled';

export interface User {
  id: string;
  name: string;
  role: string;
  status: UserStatus;
}

export interface UsersTableProps {
  users: User[];
  pageSize?: number;
}

export default function UsersTable({ users, pageSize = 10 }: UsersTableProps) {
  const [page, setPage] = useState(1);

  const pageCount = Math.max(1, Math.ceil(users.length / pageSize));
  const currentPage = Math.min(page, pageCount);

  const rows = useMemo(
    () => users.slice((currentPage - 1) * pageSize, currentPage * pageSize),
    [users, currentPage, pageSize],
  );

  return (
    <div className="jx-stack" style={{ gap: 'var(--jx-space-4)' }}>
      <table className="jx-table">
        <thead>
          <tr>
            <th scope="col">Имя</th>
            <th scope="col">Роль</th>
            <th scope="col">Статус</th>
          </tr>
        </thead>
        <tbody>
          {rows.length === 0 ? (
            <tr>
              <td colSpan={3} className="jx-table__empty">
                Пользователей нет
              </td>
            </tr>
          ) : (
            rows.map((user) => (
              <tr key={user.id}>
                <td>{user.name}</td>
                <td>{user.role}</td>
                <td>
                  <span
                    className={
                      user.status === 'active'
                        ? 'jx-badge jx-badge--success'
                        : 'jx-badge jx-badge--danger'
                    }
                  >
                    {user.status === 'active' ? 'Активен' : 'Отключён'}
                  </span>
                </td>
              </tr>
            ))
          )}
        </tbody>
      </table>

      <nav
        className="jx-cluster"
        aria-label="Постраничная навигация"
        style={{ gap: 'var(--jx-space-3)', alignItems: 'center' }}
      >
        <button
          type="button"
          className="jx-btn jx-btn--ghost"
          onClick={() => setPage(currentPage - 1)}
          disabled={currentPage <= 1}
        >
          Назад
        </button>
        <span className="jx-text jx-text--muted" aria-live="polite">
          Страница {currentPage} из {pageCount}
        </span>
        <button
          type="button"
          className="jx-btn jx-btn--ghost"
          onClick={() => setPage(currentPage + 1)}
          disabled={currentPage >= pageCount}
        >
          Вперёд
        </button>
      </nav>
    </div>
  );
}

